//! Migrations.
//!
//! A migration is one SQL file applied once, in its own transaction, and
//! recorded in `engine_migrations` with a SHA-256 checksum. Two sources feed
//! the runner, in this order:
//!
//! 1. the engine's own schema, contributed by each compiled feature crate
//!    (ids like `content/0001_base`), embedded in the binary;
//! 2. the site's `migrations/<backend>/NNNN_name.sql` files (ids like
//!    `site/0002_types_article`), most of them generated by
//!    `engine types sync`.
//!
//! Changing a migration after it was applied is an error (the checksum no
//! longer matches); write a new migration instead. Runs take a Postgres
//! advisory lock, so two `engine migrate` processes cannot interleave.
//!
//! The runner is our own rather than `sqlx::migrate::Migrator` because it
//! combines embedded per-feature migrations with a site folder chosen at run
//! time, and keeps one ordered history across both.

use std::path::Path;

use anyhow::{Context, Result, bail};
use sha2::{Digest, Sha256};

use crate::{Backend, Db};

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Migration {
    /// `<source>/<NNNN_name>`, e.g. `content/0001_base`, `site/0002_types`.
    pub id: String,
    pub sql: String,
    pub checksum: String,
}

impl Migration {
    pub fn new(id: impl Into<String>, sql: impl Into<String>) -> Self {
        let sql = sql.into();
        let checksum = format!("{:x}", Sha256::digest(sql.as_bytes()));
        Migration {
            id: id.into(),
            sql,
            checksum,
        }
    }
}

/// Folder of a site's migrations for `backend`.
pub fn site_dir(site: &Path, backend: Backend) -> std::path::PathBuf {
    site.join("migrations").join(backend.as_str())
}

/// Whether `name` is a valid migration file name: `NNNN_words.sql`.
pub fn valid_file_name(name: &str) -> bool {
    let Some(stem) = name.strip_suffix(".sql") else {
        return false;
    };
    let b = stem.as_bytes();
    b.len() > 5
        && b[..4].iter().all(u8::is_ascii_digit)
        && b[4] == b'_'
        && b[5..]
            .iter()
            .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || *c == b'_')
}

/// Read a site's migrations for `backend`, sorted by file name.
pub fn site_migrations(site: &Path, backend: Backend) -> Result<Vec<Migration>> {
    let dir = site_dir(site, backend);
    if !dir.is_dir() {
        return Ok(Vec::new());
    }
    let mut names = Vec::new();
    for entry in std::fs::read_dir(&dir).with_context(|| format!("reading {}", dir.display()))? {
        let entry = entry?;
        let name = entry.file_name().to_string_lossy().to_string();
        if !name.ends_with(".sql") {
            continue;
        }
        if !valid_file_name(&name) {
            bail!(
                "{}: migration files are named like `0001_create_things.sql` \
                 (four digits, `_`, lowercase words)",
                entry.path().display()
            );
        }
        names.push(name);
    }
    names.sort();
    let mut out = Vec::new();
    let mut numbers = std::collections::BTreeSet::new();
    for name in names {
        if !numbers.insert(name[..4].to_string()) {
            bail!(
                "two migrations in {} share the number {}",
                dir.display(),
                &name[..4]
            );
        }
        let sql = std::fs::read_to_string(dir.join(&name))?;
        out.push(Migration::new(
            format!("site/{}", name.trim_end_matches(".sql")),
            sql,
        ));
    }
    Ok(out)
}

/// One migration's state in a database.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Status {
    pub id: String,
    pub applied: bool,
}

/// Which of `migrations` are applied. Errors if an applied one changed.
pub async fn status(db: &Db, migrations: &[Migration]) -> Result<Vec<Status>> {
    let applied = applied(db).await?;
    migrations
        .iter()
        .map(|m| match applied.iter().find(|(id, _)| id == &m.id) {
            Some((_, sum)) if sum != &m.checksum => bail!(
                "migration {} was changed after it was applied; restore it and add a new \
                 migration instead",
                m.id
            ),
            Some(_) => Ok(Status {
                id: m.id.clone(),
                applied: true,
            }),
            None => Ok(Status {
                id: m.id.clone(),
                applied: false,
            }),
        })
        .collect()
}

/// Ids of pending migrations (cheap check before serving).
pub async fn pending(db: &Db, migrations: &[Migration]) -> Result<Vec<String>> {
    Ok(status(db, migrations)
        .await?
        .into_iter()
        .filter(|s| !s.applied)
        .map(|s| s.id)
        .collect())
}

/// Apply every pending migration, in order. Returns the ids applied.
pub async fn apply(db: &Db, migrations: &[Migration]) -> Result<Vec<String>> {
    match db {
        #[cfg(feature = "postgres")]
        Db::Postgres(pool) => pg::apply(pool, migrations).await,
    }
}

async fn applied(db: &Db) -> Result<Vec<(String, String)>> {
    match db {
        #[cfg(feature = "postgres")]
        Db::Postgres(pool) => pg::applied(pool).await,
    }
}

#[cfg(feature = "postgres")]
mod pg {
    use super::*;
    use sqlx::PgPool;

    /// Arbitrary constant key for `pg_advisory_lock`.
    const LOCK_KEY: i64 = 0x5752_4f55_4748_5401;

    const BOOTSTRAP: &str = "CREATE TABLE IF NOT EXISTS engine_migrations (
        id text PRIMARY KEY,
        checksum text NOT NULL,
        applied_at timestamptz NOT NULL DEFAULT now()
    )";

    async fn table_exists(pool: &PgPool) -> Result<bool> {
        let row: (bool,) = sqlx::query_as("SELECT to_regclass('engine_migrations') IS NOT NULL")
            .fetch_one(pool)
            .await?;
        Ok(row.0)
    }

    pub async fn applied(pool: &PgPool) -> Result<Vec<(String, String)>> {
        if !table_exists(pool).await? {
            return Ok(Vec::new());
        }
        let rows = sqlx::query!("SELECT id, checksum FROM engine_migrations ORDER BY id")
            .fetch_all(pool)
            .await?;
        Ok(rows.into_iter().map(|r| (r.id, r.checksum)).collect())
    }

    pub async fn apply(pool: &PgPool, migrations: &[Migration]) -> Result<Vec<String>> {
        let mut conn = pool.acquire().await?;
        sqlx::raw_sql(BOOTSTRAP).execute(&mut *conn).await?;
        sqlx::query("SELECT pg_advisory_lock($1)")
            .bind(LOCK_KEY)
            .execute(&mut *conn)
            .await?;
        let result = async {
            let done = sqlx::query!("SELECT id, checksum FROM engine_migrations")
                .fetch_all(&mut *conn)
                .await?;
            let mut ran = Vec::new();
            for m in migrations {
                if let Some(d) = done.iter().find(|d| d.id == m.id) {
                    if d.checksum != m.checksum {
                        bail!(
                            "migration {} was changed after it was applied; restore it and add \
                             a new migration instead",
                            m.id
                        );
                    }
                    continue;
                }
                let mut tx = sqlx::Connection::begin(&mut *conn).await?;
                sqlx::raw_sql(&m.sql)
                    .execute(&mut *tx)
                    .await
                    .with_context(|| format!("applying migration {}", m.id))?;
                sqlx::query!(
                    "INSERT INTO engine_migrations (id, checksum) VALUES ($1, $2)",
                    m.id,
                    m.checksum
                )
                .execute(&mut *tx)
                .await?;
                tx.commit().await?;
                ran.push(m.id.clone());
            }
            Ok(ran)
        }
        .await;
        sqlx::query("SELECT pg_advisory_unlock($1)")
            .bind(LOCK_KEY)
            .execute(&mut *conn)
            .await?;
        result
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn file_names_and_ordering() {
        assert!(valid_file_name("0001_init.sql"));
        assert!(valid_file_name("0012_types_article_v2.sql"));
        for bad in [
            "1_init.sql",
            "0001init.sql",
            "0001_Init.sql",
            "0001_.sql",
            "0001_x.txt",
        ] {
            assert!(!valid_file_name(bad), "{bad}");
        }
        let d = tempfile::tempdir().unwrap();
        let dir = site_dir(d.path(), Backend::Postgres);
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(dir.join("0002_b.sql"), "select 2").unwrap();
        std::fs::write(dir.join("0001_a.sql"), "select 1").unwrap();
        std::fs::write(dir.join("README.md"), "ignored").unwrap();
        let m = site_migrations(d.path(), Backend::Postgres).unwrap();
        let ids: Vec<_> = m.iter().map(|m| m.id.as_str()).collect();
        assert_eq!(ids, ["site/0001_a", "site/0002_b"]);
        assert_eq!(m[0].checksum.len(), 64);
        std::fs::write(dir.join("0002_c.sql"), "dup").unwrap();
        assert!(site_migrations(d.path(), Backend::Postgres).is_err());
        std::fs::remove_file(dir.join("0002_c.sql")).unwrap();
        std::fs::write(dir.join("bad.sql"), "x").unwrap();
        assert!(site_migrations(d.path(), Backend::Postgres).is_err());
    }
}
